window.external = {};
window.external.sendMessage = (data) => {

    data = JSON.parse(data);
    if (data.action)
    {
        switch (data.action)
        {
            case "loadGameCovers":
                fakeInteralCall({
                    data: {
                        gameCovers: window.fakeState.games.map(g => { 
                                return {
                                gameId: g.id,
                                coverImageDataUrl: g.coverImageDataUrl,
                        }})
                    },
                    ok:true,
                    requestId: data.requestId
                });
                break;
            case "loadState":
                fakeInteralCall({data: window.fakeState, ok:true, requestId: data.requestId});
                break;
            case "saveSettings":
                fakeInteralCall({ok:true, requestId: data.requestId, data: {settings: data.payload, games: window.fakeState.games}});
                break;
            case "refresh":
                window.location.reload();
        }
    }
};


var fakeInteralCall = (data) => {
    fakeCallFunc(JSON.stringify(data)); 
}

var fakeCallFunc = null;

window.external.receiveMessage = (data) => {
    fakeCallFunc = data;
};


